223	func aggregateGet(t *testing.T, server *httptest.Server, query string) (int, []map[string]any) {
224		t.Helper()
225		req, err := http.NewRequest(http.MethodGet, server.URL+"/metrics/aggregate"+query, nil)
226		if err != nil {
227			t.Fatal(err)
228		}
229		resp, err := http.DefaultClient.Do(req)
230		if err != nil {
231			t.Fatal(err)
232		}
233		defer resp.Body.Close()
234		raw, err := io.ReadAll(resp.Body)
235		if err != nil {
236			t.Fatal(err)
237		}
238		if resp.StatusCode >= 400 {
239			var errBody map[string]any
240			_ = json.Unmarshal(raw, &errBody)
241			return resp.StatusCode, []map[string]any{{"_error": errBody}}
242		}
243		var out []map[string]any
244		if err := json.Unmarshal(raw, &out); err != nil {
245			t.Fatalf("decode %q: %v", raw, err)
246		}
247		return resp.StatusCode, out
248	}
