265			{"outer field unicode escaped", `{"samples":[` + valid + `],"` + uEscape("0073", "amples") + `":[` + valid + `]}`},
266			{"sample field twice, same value", `{"samples":[{"id":"s9","id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
267			{"sample field null then legal", `{"samples":[{"id":null,"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
268			{"sample field unicode escaped", `{"samples":[{"id":"s9","` + uEscape("0069", "d") + `":"s10","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
269			{"labels name twice, same value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1,"labels":{"env":"prod","env":"prod"}}]}`},
270			{"labels name unicode escaped", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1,"labels":{"env":"prod","` + uEscape("0065", "nv") + `":"dev"}}]}`},
271		}
