300	func TestPostMetricsDuplicateFieldRollsBackWholeBatch(t *testing.T) {
301		mstore := &fakeMetricStorage{}
302		server := newMetricsServer(t, metrics.NewStore(), mstore)
303	
304		// One stored point in the window we will aggregate.
305		postSamples(t, server, `{"samples":[
306			{"id":"s0","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":10}
307		]}`)
308	
309		window := "?name=requests&service=gw&since=2026-10-01T10:00:00Z&until=2026-10-01T10:01:00Z&step=60"
310		firstSeg := func(t *testing.T) map[string]any {
311			t.Helper()
312			status, out := aggregateGet(t, server, window)
313			if status != http.StatusOK || len(out) != 1 {
314				t.Fatalf("aggregate %d: %v", status, out)
315			}
316			segs := out[0]["segments"].([]any)
317			if len(segs) != 1 {
318				t.Fatalf("one segment: %v", segs)
319			}
320			return segs[0].(map[string]any)
321		}
322		before := firstSeg(t)
323		if int(number(before["count"])) != 1 || before["delta"].(float64) != 0 {
324			t.Fatalf("baseline: %v", before)
325		}
326	
327		// A valid new sample followed by a sample with a duplicated field: the
328		// whole request is input-shaped rejection, and the leading sample must
329		// neither reach durable storage nor take its id or timestamp.
330		status, out := metricsDo(t, server, http.MethodPost, "/metrics", `{"samples":[
331			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:30Z","value":12},
332			{"id":"x1","id":"x2","service":"gw","name":"requests","at":"2026-10-01T10:00:40Z","value":1}
333		]}`)
334		if status != http.StatusBadRequest || out["error"] == "" {
335			t.Fatalf("trailing duplicate field must be 400, got %d %v", status, out)
336		}
337		if len(mstore.batches) != 1 {
338			t.Fatalf("rejected batch must never reach durable storage, appended %d batches", len(mstore.batches))
339		}
340		if seg := firstSeg(t); seg["count"] != before["count"] || seg["delta"] != before["delta"] {
341			t.Fatalf("stored series changed after rejection: before %v, after %v", before, seg)
342		}
343	
344		// The same batch carrying content that would 409 against the stored
345		// sample still answers 400: format rejection precedes conflict handling.
346		status, out = metricsDo(t, server, http.MethodPost, "/metrics", `{"samples":[
347			{"id":"s0","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":99},
348			{"id":"x1","id":"x2","service":"gw","name":"requests","at":"2026-10-01T10:00:40Z","value":1}
349		]}`)
350		if status != http.StatusBadRequest || out["error"] == "" {
351			t.Fatalf("duplicate field plus stored conflict must stay 400, got %d %v", status, out)
352		}
353		if seg := firstSeg(t); seg["count"] != before["count"] || seg["delta"] != before["delta"] {
354			t.Fatalf("stored series changed after mixed rejection: before %v, after %v", before, seg)
355		}
356	
357		// With the duplicate removed, the previously rejected id and timestamp
358		// are free and the samples ingest normally.
359		out = postSamples(t, server, `{"samples":[
360			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:30Z","value":12},
361			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:01:00Z","value":15}
362		]}`)
363		if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
364			t.Fatalf("recovery ingestion: %v", out)
365		}
366	
367		// Half-open window: s1 joins s0 in [10:00,10:01) with delta +2; the point
368		// at exactly 10:01 stays out of that window and lands in the next one.
369		seg := firstSeg(t)
370		if int(number(seg["count"])) != 2 || seg["delta"].(float64) != 2 {
371			t.Fatalf("window after recovery: %v", seg)
372		}
373		nextWindow := "?name=requests&service=gw&since=2026-10-01T10:01:00Z&until=2026-10-01T10:02:00Z&step=60"
374		nextStatus, nextAgg := aggregateGet(t, server, nextWindow)
375		if nextStatus != http.StatusOK || len(nextAgg) != 1 {
376			t.Fatalf("next window: %d %v", nextStatus, nextAgg)
377		}
378		nextSeg := nextAgg[0]["segments"].([]any)[0].(map[string]any)
379		if int(number(nextSeg["count"])) != 1 || nextSeg["delta"].(float64) != 3 {
380			t.Fatalf("point at window end must move to next segment (+3): %v", nextSeg)
381		}
382	}
