117	func (h *Handler) getMetricsAggregate(w http.ResponseWriter, r *http.Request) {
118		if h.metricsUnavailable(w) {
119			return
120		}
121	
122		values := r.URL.Query()
123	
124		name, ok := singleValue(values, "name")
125		if !ok || strings.TrimSpace(name) == "" {
126			writeError(w, http.StatusBadRequest, "name is required and must be a single non-empty value")
127			return
128		}
129	
130		parseTime := func(param string) (time.Time, bool) {
131			raw, ok := singleValue(values, param)
132			if !ok || raw == "" {
133				writeError(w, http.StatusBadRequest, param+" is required and must be a single RFC3339Nano timestamp")
134				return time.Time{}, false
135			}
136			parsed, err := time.Parse(time.RFC3339Nano, raw)
137			if err != nil {
138				writeError(w, http.StatusBadRequest, param+" must be an RFC3339Nano timestamp")
139				return time.Time{}, false
140			}
141			return parsed, true
142		}
143		since, ok := parseTime("since")
144		if !ok {
145			return
146		}
147		until, ok := parseTime("until")
148		if !ok {
149			return
150		}
151		if !since.Before(until) {
152			writeError(w, http.StatusBadRequest, "since must be strictly before until")
153			return
154		}
155	
156		rawStep, ok := singleValue(values, "step")
157		if !ok || rawStep == "" {
158			writeError(w, http.StatusBadRequest, "step is required and must be a single integer number of seconds")
159			return
160		}
161		if !isDecimal(rawStep) {
162			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
163			return
164		}
165		stepSeconds, err := strconv.ParseInt(rawStep, 10, 64)
166		if err != nil || stepSeconds < minStepSeconds || stepSeconds > maxStepSeconds {
167			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
168			return
169		}
170	
171		// service is optional but, like the other parameters, may not repeat.
172		var service string
173		if rawServices, present := values["service"]; present {
174			if len(rawServices) != 1 {
175				writeError(w, http.StatusBadRequest, "service must be a single value")
176				return
177			}
178			service = rawServices[0]
179		}
180	
181		labels, lerr := events.ParseLabelConditions(values["label"])
182		if lerr != nil {
183			writeError(w, http.StatusBadRequest, lerr.Error())
184			return
185		}
186	
187		query := metrics.AggregateQuery{
188			Name:    name,
189			Service: service,
190			Since:   since,
191			Until:   until,
192			Step:    time.Duration(stepSeconds) * time.Second,
193			Labels:  labels,
194		}
195		found, aerr := h.metrics.Aggregate(query)
196		if aerr != nil {
197			switch {
198			case errors.Is(aerr, metrics.ErrTooManySegments):
199				writeError(w, http.StatusBadRequest, "window must not require more than 10000 segments")
200			case errors.Is(aerr, metrics.ErrTooManySeriesSegments):
201				writeError(w, http.StatusBadRequest, "aggregate must not contain more than 100000 series segments")
202			case errors.Is(aerr, metrics.ErrDeltaNotFinite):
203				writeError(w, http.StatusUnprocessableEntity, "aggregate delta total is not a finite number")
204			default:
205				writeError(w, http.StatusBadRequest, "invalid aggregate query")
206			}
207			return
208		}
209	
210		writeAggregate(w, found)
211	}
212	
213	// writeAggregate renders one entry per matching series; a result with no
214	// matching series is an empty JSON array.
215	func writeAggregate(w http.ResponseWriter, found []metrics.AggregateSeries) {
216		dtos := make([]aggregateSeriesDTO, 0, len(found))
217		for _, series := range found {
218			segments := make([]aggregateSegmentDTO, len(series.Segments))
219			for i, segment := range series.Segments {
220				segments[i] = aggregateSegmentDTO{
221					Since: utcRFC3339Nano(segment.Start),
222					Until: utcRFC3339Nano(segment.End),
223					Count: segment.Count,
224					Delta: segment.Delta,
225				}
226			}
227			dtos = append(dtos, aggregateSeriesDTO{
228				Service:  series.Service,
229				Labels:   series.Labels,
230				Segments: segments,
231			})
232		}
233		writeJSON(w, http.StatusOK, dtos)
234	}
